const clients = Object.values(msg.payload || {});
const rayvn = clients.find(client => client.client_system === "rayvn");

if (!rayvn) {
    node.error("Rayvn client not found in joined config payload", { _msgid: msg._msgid });
    return null;
}

const api_key = rayvn.client_specific?.api_key || rayvn.api_key;
if (!api_key) {
    node.error("Rayvn API key missing on Rayvn client", { _msgid: msg._msgid });
    return null;
}

const parts = api_key.split(".");
if (parts.length < 2) {
    node.error("Rayvn API key does not contain a decodable middle segment", { _msgid: msg._msgid });
    return null;
}

const base64url = parts[1];
const base64 = base64url
    .replace(/-/g, "+")
    .replace(/_/g, "/")
    .padEnd(Math.ceil(base64url.length / 4) * 4, "=");

let decoded;
let payload;

try {
    decoded = Buffer.from(base64, "base64").toString("utf8");
    payload = JSON.parse(decoded);
} catch (err) {
    node.error("Failed to decode Rayvn API key payload: " + err.message, { _msgid: msg._msgid });
    return null;
}

const group_id = payload.group?.id;
if (!group_id) {
    node.error("group.id missing from decoded Rayvn API key payload", { _msgid: msg._msgid });
    return null;
}

msg.rayvn_client = rayvn;
msg.rayvn_group_id = group_id;

return msg;

const rayvn = msg.rayvn_client;
const group_id = msg.rayvn_group_id;

if (!rayvn || !group_id) {
    node.error("Missing Rayvn client or group id before tag creation", msg);
    return null;
}

const base_url = global.get("parat_bridge").base_urls.rayvn;
const auth_key = rayvn.client_specific?.api_key || rayvn.api_key;

const tags = [
    {
        key: "parat_bridge",
        name: "Parat Bridge",
        colorHex: "#b80d18"
    },
    {
        key: "wasos",
        name: "WaSOS",
        colorHex: "#828d62"
    }
];

const messages = tags.map((tag, index) => ({
    ...msg,
    joined_payload: msg.payload,
    parts: {
        id: msg._msgid + "-rayvn-tags",
        type: "array",
        count: tags.length,
        index: index
    },
    _tag_key: tag.key,
    _tag_name: tag.name,
    url: base_url + "/tags",
    method: "POST",
    headers: {
        "Authorization": "Bearer " + auth_key,
        "Content-Type": "application/json",
        "Accept": "application/json"
    },
    payload: JSON.stringify({
        name: tag.name,
        group: {
            id: group_id
        },
        type: "LOG_ENTRY",
        colorHex: tag.colorHex,
        groupScopeType: "LOCAL"
    })
}));

return [messages];

const responses = Array.isArray(msg.payload) ? msg.payload : [msg.payload];

const connection_tags = {
    parat_bridge: null,
    wasos: null
};

let joined_payload = null;

for (const item of responses) {
    if (!joined_payload && item.joined_payload) {
        joined_payload = item.joined_payload;
    }

    const tag_key = item._tag_key;
    const tag_id = item.payload?.id;

    if (!tag_key) {
        node.error("Joined Rayvn tag response missing _tag_key", { _msgid: msg._msgid });
        return null;
    }

    if (!tag_id) {
        node.error("Joined Rayvn tag response missing payload.id", { _msgid: msg._msgid, tag_key: tag_key });
        return null;
    }

    connection_tags[tag_key] = tag_id;
}

if (!joined_payload || Array.isArray(joined_payload)) {
    node.error("Original joined client payload was not preserved through Rayvn tag creation", { _msgid: msg._msgid });
    return null;
}

return {
    _msgid: msg._msgid,
    payload: joined_payload,
    connection_tags: connection_tags
};
